from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()


@app.get("/limited", rate_limit="50/minute")
def limited():
    return {"ok": True}


@app.get("/unlimited")
def unlimited():
    return {"ok": True}


client = TestClient(app)


def test_limited_endpoint_surfaces_x_rate_limit_in_openapi():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    openapi = response.json()
    assert openapi["paths"]["/limited"]["get"]["x-rate-limit"] == "50/minute"


def test_unlimited_endpoint_omits_x_rate_limit_in_openapi():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    openapi = response.json()
    assert "x-rate-limit" not in openapi["paths"]["/unlimited"]["get"]


def test_limited_endpoint_still_serves_requests():
    response = client.get("/limited")
    assert response.status_code == 200, response.text
    assert response.json() == {"ok": True}


def test_unlimited_endpoint_still_serves_requests():
    response = client.get("/unlimited")
    assert response.status_code == 200, response.text
    assert response.json() == {"ok": True}

